using Godot;
using System.Collections.Generic;

namespace Aetheris;

/// <summary>One drawn tree variant from assets/foliage/trees (generated by tools/make_trees.py).</summary>
public sealed class TreeVariant
{
    public string File { get; init; } = "";
    public string Species { get; init; } = "";
    public int Width { get; init; }
    public int Height { get; init; }
    public int HeightTiles { get; init; }
    public float Weight { get; init; }
    public int TrunkPixels { get; init; }

    /// <summary>Fraction of the tree's height, measured from the ground, where leaves begin to flutter.</summary>
    public float LeafStart { get; init; }

    public float Sway { get; init; }
    public int BareRows { get; init; }
    public Texture2D Texture => TreeCatalog.TextureOf(this);
}

public static class TreeCatalog
{
    private const string Folder = "res://assets/foliage/trees/";
    private static readonly Dictionary<string, Texture2D> Textures = new();

    /// <summary>Pixels of each sprite that sit below the ground line.</summary>
    public static int Embed { get; private set; }

    public static IReadOnlyList<TreeVariant> Variants { get; } = Load();

    private static List<TreeVariant> Load()
    {
        var list = new List<TreeVariant>();
        using var file = FileAccess.Open(Folder + "trees.json", FileAccess.ModeFlags.Read);
        var data = Json.ParseString(file.GetAsText()).AsGodotDictionary();
        Embed = data["embed"].AsInt32();
        foreach (Variant item in data["trees"].AsGodotArray())
        {
            var entry = item.AsGodotDictionary();
            list.Add(new TreeVariant
            {
                File = entry["file"].AsString(),
                Species = entry["species"].AsString(),
                Width = entry["width"].AsInt32(),
                Height = entry["height"].AsInt32(),
                HeightTiles = entry["height_tiles"].AsInt32(),
                Weight = entry["weight"].AsSingle(),
                TrunkPixels = entry["trunk_px"].AsInt32(),
                LeafStart = entry["leaf_start"].AsSingle(),
                Sway = entry["sway"].AsSingle(),
                BareRows = entry["bare_rows"].AsInt32(),
            });
        }
        return list;
    }

    public static Texture2D TextureOf(TreeVariant variant)
    {
        if (!Textures.TryGetValue(variant.File, out var texture))
            Textures[variant.File] = texture = GD.Load<Texture2D>(Folder + variant.File);
        return texture;
    }

    /// <summary>Weighted pick of a variant from a value in [0, 1).</summary>
    public static TreeVariant Pick(double roll)
    {
        float total = 0f;
        foreach (var variant in Variants) total += variant.Weight;
        double remaining = roll * total;
        foreach (var variant in Variants)
        {
            remaining -= variant.Weight;
            if (remaining <= 0) return variant;
        }
        return Variants[^1];
    }
}
